<!-- This file is generated by AI. -->
<!--
  编辑角色对话框: 名称 / ID / 两个 GPT-SoVITS 模型 / 描述, 以及**下方的参考音频编辑列表**
  (搜索 / 增删 / 试听, 见 `ReferenceListEditor`)。

  **改动即时生效**, 没有"保存"按钮: 输入框失焦、下拉选中都会立刻落盘, 底部按钮只是"关闭"。
  参考音频列表**自己滚动**, 而不是把整个对话框撑长。

  `hideModel` 用于「选择角色」对话框里点开的那一份: 那里只是看看/改改这个角色的参考音频,
  而**权重是服务端本机的路径**, 与"这个角色叫什么、有哪些参考音频"无关。

  ⚠️ 不带 `<style>` 块 —— 类名来自全局 `styles.css`。
-->
<script lang="ts">
  import { save as saveDialog } from '@tauri-apps/plugin-dialog';
  import { untrack } from 'svelte';

  import { voiceExportCharacter, type Character, type ModelCandidate } from '../commands/voice';
  import { appStore } from '../state/store.svelte';
  import { voiceController } from '../voice/controller';
  import { errorSummary } from '../voice/errorText';
  import AppDialog from './AppDialog.svelte';
  import Button from './Button.svelte';
  import ReferenceListEditor from './ReferenceListEditor.svelte';
  import Select from './Select.svelte';

  let {
    character,
    models = [],
    /** 隐藏「GPT-SoVITS 模型」一项 (在「选择角色」里点开时) */
    hideModel = false,
    onClose,
    /**
     * 内容已变化, 参数是**落盘后的这一份**。
     *
     * 必须是新对象而不是"让调用方拿旧 id 去查": 改角色 ID 时旧 id 已经不存在了,
     * 调用方按旧 id 查会查不到, 于是界面表现为"输入 ID 之后对话框自己关掉了"。
     */
    onChanged,
    onError,
  }: {
    character: Character;
    models?: ModelCandidate[];
    hideModel?: boolean;
    onClose: () => void;
    onChanged?: (character: Character) => void;
    onError?: (error: string | null) => void;
  } = $props();

  /*
   * 草稿的**初值**只取一次; 之后的同步交给下面那个 `$effect`。`untrack` 把"只取初值"写成
   * 显式意图, 否则编译器会报 `state_referenced_locally` (它无法区分"漏了响应式"与"故意取一次")。
   */
  let draft = $state<Character>(untrack(() => ({ ...character })));
  /** 已经落盘的 id; 与 `draft.id` 不同表示用户改了 id (需要搬移参考音频目录) */
  let savedId = $state(untrack(() => character.id));

  /*
   * 外部这一份更新了 (改名 / 改描述 / 参考音频增删) 就换成它。
   *
   * 只认 `id` 与 `updatedAt` 两个键: 用户"正在输入、还没失焦"的字段会被后一次落盘覆盖。
   */
  $effect(() => {
    const id = character.id;
    const stamp = character.updatedAt;
    void id;
    void stamp;
    draft = { ...character };
    savedId = character.id;
  });

  /**
   * 立即落盘 (没有"保存"按钮)。
   *
   * 默认走**字段补丁** (`updateCharacter`): 只发送这一项改动, 服务端读-改-写,
   * 因此不会把别的字段回写成过时快照。
   *
   * 唯一例外是**改名**: `id` 本身变了, 没法用字段补丁表达 (服务端要据此搬移参考
   * 音频目录), 那种情况才发送整份记录。
   */
  async function commit(patch: Partial<Character>): Promise<void> {
    const next = { ...draft, ...patch };
    draft = next;
    try {
      const renamed = typeof patch.id === 'string' && patch.id !== savedId;
      const saved = renamed
        ? await voiceController.persistCharacter(next, savedId)
        : await voiceController.updateCharacter(savedId, patch);
      savedId = saved.id;
      draft = { ...saved };
      onError?.(null);
      onChanged?.(saved);
    } catch (caught) {
      // 失败时回滚到已落盘的状态, 避免界面显示一个并不存在的 id
      draft = { ...draft, id: savedId };
      onError?.(errorSummary(String(caught)));
    }
  }

  /**
   * 参考音频增删后, 把**列表**换成刚落盘的那一份。
   *
   * 只合并 `references`: 名称 / 描述这些字段可能还停在"正在输入、尚未失焦"的状态,
   * 整份覆盖会把用户刚敲的字抹掉。
   */
  function syncReferences(): void {
    const latest = appStore.voiceCharacters.find((item) => item.id === savedId);
    if (!latest) return;
    const merged = { ...draft, references: latest.references };
    draft = merged;
    onChanged?.(merged);
  }

  async function exportCharacter(): Promise<void> {
    const destination = await saveDialog({
      defaultPath: `${draft.name}.zip`,
      filters: [{ name: 'Zip 压缩包', extensions: ['zip'] }],
    });
    if (typeof destination !== 'string') return;
    await voiceExportCharacter(character.id, destination);
  }

  /** 权重路径的后缀名 (权重文件名的可读部分) */
  function suffixOf(weights: string | null | undefined): string {
    if (!weights) return '';
    return weights.replace(/\\/g, '/').split('/').pop() ?? weights;
  }

  const gptOptions = $derived(models.map((item) => ({ value: item.gptWeights, label: suffixOf(item.gptWeights) })));
  const sovitsOptions = $derived(
    models.map((item) => ({ value: item.sovitsWeights, label: suffixOf(item.sovitsWeights) }))
  );
  /** 当前权重不在候选里时留空, 让下拉显示 placeholder */
  const gptValue = $derived(
    models.some((item) => item.gptWeights === draft.model?.gptWeights) ? (draft.model?.gptWeights ?? '') : ''
  );
  const sovitsValue = $derived(
    models.some((item) => item.sovitsWeights === draft.model?.sovitsWeights) ? (draft.model?.sovitsWeights ?? '') : ''
  );
</script>

<AppDialog title={`编辑角色 · ${character.name}`} size="large" height={640} compact {onClose}>
  <div class="role-edit-form">
    <label class="voice-field">
      <span class="voice-label">角色名</span>
      <input
        class="ui-input"
        value={draft.name}
        placeholder="角色名"
        oninput={(event) => (draft = { ...draft, name: event.currentTarget.value })}
        onblur={() => void commit({ name: draft.name })}
      />
    </label>

    <label class="voice-field">
      <span class="voice-label">角色 ID</span>
      <input
        class="ui-input"
        value={draft.id}
        placeholder="角色 ID"
        title="同时是配置文件名与 game/vocal 下的目录名"
        oninput={(event) => (draft = { ...draft, id: event.currentTarget.value })}
        onblur={() => void commit({ id: draft.id })}
      />
    </label>

    {#if !hideModel}
      <div class="voice-field role-edit-span">
        <span class="voice-label">GPT-SoVITS 模型</span>
        <div class="role-edit-models">
          <Select
            placeholder="选择 GPT 权重"
            value={gptValue}
            title={suffixOf(draft.model?.gptWeights) || '未指定 GPT 权重'}
            options={gptOptions}
            onchange={(gptWeights) => void commit({ model: { ...(draft.model ?? {}), gptWeights } })}
          />
          <Select
            placeholder="选择 SoVITS 权重"
            value={sovitsValue}
            title={suffixOf(draft.model?.sovitsWeights) || '未指定 SoVITS 权重'}
            options={sovitsOptions}
            onchange={(sovitsWeights) => void commit({ model: { ...(draft.model ?? {}), sovitsWeights } })}
          />
        </div>
      </div>
    {/if}

    <label class="voice-field role-edit-span">
      <span class="voice-label">描述</span>
      <textarea
        class="ui-input character-description"
        rows="3"
        value={draft.description}
        oninput={(event) => (draft = { ...draft, description: event.currentTarget.value })}
        onblur={() => void commit({ description: draft.description })}></textarea>
    </label>
  </div>

  <!-- 参考音频列表 (搜索 + 增删 + 试听), 与「选择参考音频」对话框是同一个组件 -->
  <ReferenceListEditor character={draft} onChanged={syncReferences} />

  {#snippet footerLeading()}
    <Button icon="ArrowDownload" onclick={() => void exportCharacter()}>导出角色</Button>
  {/snippet}

  {#snippet footer()}
    <Button appearance="primary" onclick={onClose}>关闭</Button>
  {/snippet}
</AppDialog>
